public protocol NativePorts: AnyObject, Sendable {
    
    func storageGet(key: String)  -> String?
    
    func storageSet(key: String, value: String) 
    
    func storageRemove(key: String) 
    
    /**
     * In-app navigation requested by core (a history entry or a replacement).
     */
    func navigate(path: String, replace: Bool) 
    
    /**
     * Leave the app: Google authorization or a locale switch, in a Custom Tab or
     * an authentication session.
     */
    func leave(url: String) 
    
    func calendar()  -> CalendarOffsets
    
    /**
     * Seconds, or `None` when the file could not be measured.
     */
    func measure(file: UInt64)  -> Double?
    
    /**
     * One PUT of the held file; `true` only when the host answered 200.
     */
    func upload(file: UInt64, url: String, progress: ProgressSink)  -> Bool
    
    func release(file: UInt64) 
    
    /**
     * Pauses the mounted player; whether it was playing before.
     */
    func pausePlayer()  -> Bool
    
    func resumePlayer() 
    
    func seekPlayer(seconds: Double) 
    
    func copy(text: String, html: String?)  -> Bool
    
    func save(bytes: Data, filename: String, mime: String)  -> Bool
    
    func preview(bytes: Data, filename: String, mime: String)  -> Bool
    
    func share(bytes: Data, filename: String, mime: String)  -> ShareResult
    
    func asset(name: String)  -> Data?
    
}
